def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    padded = [[0] * (cols + 2) for _ in range(rows + 2)]
    for r in range(rows):
        for c in range(cols):
            padded[r + 1][c + 1] = grid[r][c]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = [[False] * (cols + 2) for _ in range(rows + 2)]
    queue = [(0, 0)]
    visited[0][0] = True

    while queue:
        r, c = queue.pop(0)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows + 2 and 0 <= nc < cols + 2:
                if not visited[nr][nc] and padded[nr][nc] == 0:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    for r in range(rows):
        for c in range(cols):
            nr, nc = r + 1, c + 1
            if padded[nr][nc] == 0:
                if not visited[nr][nc]:
                    result[r][c] = 8

    return result

